16	  let healthStore = HKHealthStore()
17	  let stepType = HKQuantityType.quantityType(forIdentifier: .stepCount)!
18	
19	  public func definition() -> ModuleDefinition {
20	    Name("HealthKitStep")
21	
22	    AsyncFunction("getAuthorizationStatus") { () -> String in
23	      self.authorizationStatusString()
24	    }
25	
26	    AsyncFunction("requestAuthorization") { () -> String in
27	      guard HKHealthStore.isHealthDataAvailable() else {
28	        throw HealthKitStepError.notAvailable
29	      }
30	      try await self.healthStore.requestAuthorization(toShare: [self.stepType], read: [self.stepType])
31	      return self.authorizationStatusString()
32	    }
33	
34	    AsyncFunction("logSteps") { (count: Double) in
35	      guard HKHealthStore.isHealthDataAvailable() else {
36	        throw HealthKitStepError.notAvailable
37	      }
38	      let now = Date()
39	      let quantity = HKQuantity(unit: .count(), doubleValue: count)
40	      let sample = HKQuantitySample(type: self.stepType, quantity: quantity, start: now, end: now)
41	      try await self.healthStore.save(sample)
42	    }
43	
44	    AsyncFunction("queryDailyTotals") { (days: Int) -> [[String: Any]] in
45	      guard HKHealthStore.isHealthDataAvailable() else {
46	        throw HealthKitStepError.notAvailable
47	      }
48	      return try await self.dailyTotals(days: days)
49	    }
50	  }
51	
52	  private func authorizationStatusString() -> String {
53	    switch healthStore.authorizationStatus(for: stepType) {
54	    case .notDetermined:
55	      return "notDetermined"
56	    case .sharingDenied:
57	      return "denied"
58	    case .sharingAuthorized:
59	      return "authorized"
60	    @unknown default:
61	      return "notDetermined"
62	    }
63	  }
64	
65	  private func dailyTotals(days: Int) async throws -> [[String: Any]] {
66	    let calendar = Calendar.current
67	    let startOfToday = calendar.startOfDay(for: Date())
68	    guard let startDate = calendar.date(byAdding: .day, value: -(days - 1), to: startOfToday),
69	      let endDate = calendar.date(byAdding: .day, value: 1, to: startOfToday)
70	    else {
71	      return []
72	    }
73	
74	    let predicate = HKQuery.predicateForSamples(withStart: startDate, end: endDate, options: .strictStartDate)
75	    var intervalComponents = DateComponents()
76	    intervalComponents.day = 1
77	
78	    return try await withCheckedThrowingContinuation { continuation in
79	      let query = HKStatisticsCollectionQuery(
80	        quantityType: stepType,
81	        quantitySamplePredicate: predicate,
82	        options: .cumulativeSum,
83	        anchorDate: startDate,
84	        intervalComponents: intervalComponents
85	      )
86	
87	      query.initialResultsHandler = { _, results, error in
88	        if let error {
89	          continuation.resume(throwing: error)
90	          return
91	        }
92	        var totals: [[String: Any]] = []
93	        results?.enumerateStatistics(from: startDate, to: endDate) { statistics, _ in
94	          let steps = statistics.sumQuantity()?.doubleValue(for: .count()) ?? 0
95	          totals.append([
96	            "startOfDayMillis": statistics.startDate.timeIntervalSince1970 * 1000,
97	            "steps": steps,
98	          ])
99	        }
100	        continuation.resume(returning: totals)
101	      }
102	
103	      healthStore.execute(query)
104	    }
105	  }
106	}
